package com.unicare.dispensary.message;import com.unicare.dispensary.student.*;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class MessageService{private final MessageRepository messages;private final StudentRepository students;public MessageService(MessageRepository m,StudentRepository s){messages=m;students=s;}@Transactional public MessageResponse create(String email,MessageRequest r){Student s=students.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student not found."));return MessageResponse.from(messages.save(new DispensaryMessage(s,r.subject().trim(),r.body().trim())));}@Transactional(readOnly=true)public List<MessageResponse> mine(String email){Student s=students.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student not found."));return messages.findByStudentIdOrderByCreatedAtDesc(s.getId()).stream().map(MessageResponse::from).toList();}@Transactional(readOnly=true)public List<MessageResponse> all(){return messages.findAllByOrderByCreatedAtDesc().stream().map(MessageResponse::from).toList();}@Transactional public MessageResponse reply(Long id,String staff,String body){DispensaryMessage m=find(id);if(m.getStatus()==MessageStatus.CLOSED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Conversation is closed.");m.reply(staff,body.trim());return MessageResponse.from(m);}@Transactional public void close(Long id){DispensaryMessage m=find(id);m.close();}@Transactional public MessageResponse closeWithBody(Long id){DispensaryMessage m=find(id);m.close();return MessageResponse.from(m);}private DispensaryMessage find(Long id){return messages.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Message not found."));}}
